def _lround(value):
    """C lround: nearest integer, ties away from zero."""
    if value >= 0:
        return int(math.floor(value + 0.5))
    return int(math.ceil(value - 0.5))


def _pos_angle_rads(rads):
    tmp = rads + M_2PI if rads < 0.0 else rads
    if rads >= M_2PI:
        tmp -= M_2PI
    return tmp


def _geo_azimuth_rads(p1, p2):
    return math.atan2(
        math.cos(p2[0]) * math.sin(p2[1] - p1[1]),
        math.cos(p1[0]) * math.sin(p2[0])
        - math.sin(p1[0]) * math.cos(p2[0]) * math.cos(p2[1] - p1[1]),
    )


def _ijk_normalize(c):
    if c[0] < 0:
        c[1] -= c[0]
        c[2] -= c[0]
        c[0] = 0
    if c[1] < 0:
        c[0] -= c[1]
        c[2] -= c[1]
        c[1] = 0
    if c[2] < 0:
        c[0] -= c[2]
        c[1] -= c[2]
        c[2] = 0
    minimum = c[0]
    if c[1] < minimum:
        minimum = c[1]
    if c[2] < minimum:
        minimum = c[2]
    if minimum > 0:
        c[0] -= minimum
        c[1] -= minimum
        c[2] -= minimum


def _hex2d_to_coord_ijk(x, y):
    h = [0, 0, 0]
    a1 = math.fabs(x)
    a2 = math.fabs(y)
    x2 = a2 * M_RSIN60
    x1 = a1 + x2 / 2.0
    m1 = int(x1)
    m2 = int(x2)
    r1 = x1 - m1
    r2 = x2 - m2
    if r1 < 0.5:
        if r1 < 1.0 / 3.0:
            if r2 < (1.0 + r1) / 2.0:
                h[0] = m1
                h[1] = m2
            else:
                h[0] = m1
                h[1] = m2 + 1
        else:
            if r2 < (1.0 - r1):
                h[1] = m2
            else:
                h[1] = m2 + 1
            if (1.0 - r1) <= r2 and r2 < (2.0 * r1):
                h[0] = m1 + 1
            else:
                h[0] = m1
    else:
        if r1 < 2.0 / 3.0:
            if r2 < (1.0 - r1):
                h[1] = m2
            else:
                h[1] = m2 + 1
            if (2.0 * r1 - 1.0) < r2 and r2 < (1.0 - r1):
                h[0] = m1
            else:
                h[0] = m1 + 1
        else:
            if r2 < (r1 / 2.0):
                h[0] = m1 + 1
                h[1] = m2
            else:
                h[0] = m1 + 1
                h[1] = m2 + 1
    if x < 0.0:
        if (h[1] % 2) == 0:
            axisi = h[1] // 2
            diff = h[0] - axisi
            h[0] = int(h[0] - 2.0 * diff)
        else:
            axisi = (h[1] + 1) // 2
            diff = h[0] - axisi
            h[0] = int(h[0] - (2.0 * diff + 1))
    if y < 0.0:
        h[0] = h[0] - (2 * h[1] + 1) // 2
        h[1] = -1 * h[1]
    _ijk_normalize(h)
    return h


def _up_ap7(ijk):
    i = ijk[0] - ijk[2]
    j = ijk[1] - ijk[2]
    ijk[0] = _lround((3 * i - j) * M_ONESEVENTH)
    ijk[1] = _lround((i + 2 * j) * M_ONESEVENTH)
    ijk[2] = 0
    _ijk_normalize(ijk)


def _up_ap7r(ijk):
    i = ijk[0] - ijk[2]
    j = ijk[1] - ijk[2]
    ijk[0] = _lround((2 * i + j) * M_ONESEVENTH)
    ijk[1] = _lround((3 * j - i) * M_ONESEVENTH)
    ijk[2] = 0
    _ijk_normalize(ijk)


def _down_ap7(ijk):
    i_vec = [3 * ijk[0], 0, 1 * ijk[0]]
    j_vec = [1 * ijk[1], 3 * ijk[1], 0]
    k_vec = [0, 1 * ijk[2], 3 * ijk[2]]
    ijk[0] = i_vec[0] + j_vec[0] + k_vec[0]
    ijk[1] = i_vec[1] + j_vec[1] + k_vec[1]
    ijk[2] = i_vec[2] + j_vec[2] + k_vec[2]
    _ijk_normalize(ijk)


def _down_ap7r(ijk):
    i_vec = [3 * ijk[0], 1 * ijk[0], 0]
    j_vec = [0, 3 * ijk[1], 1 * ijk[1]]
    k_vec = [1 * ijk[2], 0, 3 * ijk[2]]
    ijk[0] = i_vec[0] + j_vec[0] + k_vec[0]
    ijk[1] = i_vec[1] + j_vec[1] + k_vec[1]
    ijk[2] = i_vec[2] + j_vec[2] + k_vec[2]
    _ijk_normalize(ijk)


def _unit_ijk_to_digit(ijk):
    c = list(ijk)
    _ijk_normalize(c)
    for digit, vec in enumerate(UNIT_VECS):
        if c[0] == vec[0] and c[1] == vec[1] and c[2] == vec[2]:
            return digit
    return INVALID_DIGIT


def _rotate60ccw_digit(digit):
    return {1: 5, 5: 4, 4: 6, 6: 2, 2: 3, 3: 1}.get(digit, digit)


def _rotate60cw_digit(digit):
    return {1: 3, 3: 2, 2: 6, 6: 4, 4: 5, 5: 1}.get(digit, digit)


def _h3_get_resolution(h):
    return (h >> H3_RES_OFFSET) & 15


def _h3_get_digit(h, res):
    return (h >> ((MAX_H3_RES - res) * H3_PER_DIGIT_OFFSET)) & 7


def _h3_set_digit(h, res, digit):
    shift = (MAX_H3_RES - res) * H3_PER_DIGIT_OFFSET
    return (h & ~(7 << shift)) | ((digit & 7) << shift)


def _h3_leading_nonzero(h):
    resolution = _h3_get_resolution(h)
    for r in range(1, resolution + 1):
        digit = _h3_get_digit(h, r)
        if digit:
            return digit
    return 0


def _h3_rotate60ccw(h):
    resolution = _h3_get_resolution(h)
    for r in range(1, resolution + 1):
        h = _h3_set_digit(h, r, _rotate60ccw_digit(_h3_get_digit(h, r)))
    return h


def _h3_rotate60cw(h):
    resolution = _h3_get_resolution(h)
    for r in range(1, resolution + 1):
        h = _h3_set_digit(h, r, _rotate60cw_digit(_h3_get_digit(h, r)))
    return h


def _h3_rotate_pent60ccw(h):
    found = False
    resolution = _h3_get_resolution(h)
    for r in range(1, resolution + 1):
        h = _h3_set_digit(h, r, _rotate60ccw_digit(_h3_get_digit(h, r)))
        if not found and _h3_get_digit(h, r) != 0:
            found = True
            if _h3_leading_nonzero(h) == K_AXES_DIGIT:
                h = _h3_rotate60ccw(h)
    return h


def _geo_to_closest_face(lat, lng):
    r = math.cos(lat)
    v = (math.cos(lng) * r, math.sin(lng) * r, math.sin(lat))
    face = 0
    sqd = 5.0
    for index, center in enumerate(FACE_CENTER_POINT):
        dist = (center[0] - v[0]) ** 2 + (center[1] - v[1]) ** 2 + (center[2] - v[2]) ** 2
        if dist < sqd:
            face = index
            sqd = dist
    return face, sqd


def _geo_to_hex2d(lat, lng, res):
    face, sqd = _geo_to_closest_face(lat, lng)
    r = math.acos(1 - sqd * 0.5)
    if r < EPSILON:
        return face, 0.0, 0.0
    theta = _pos_angle_rads(
        FACE_AXES_AZ_RADS_CII[face][0]
        - _pos_angle_rads(_geo_azimuth_rads(FACE_CENTER_GEO[face], (lat, lng)))
    )
    if res % 2:
        theta = _pos_angle_rads(theta - M_AP7_ROT_RADS)
    r = math.tan(r)
    r *= INV_RES0_U_GNOMONIC
    for _ in range(res):
        r *= M_SQRT7
    return face, r * math.cos(theta), r * math.sin(theta)


def _face_ijk_to_h3(face, coord, res):
    h = H3_INIT
    h |= H3_CELL_MODE << H3_MODE_OFFSET
    h |= res << H3_RES_OFFSET
    ijk = list(coord)
    if res == 0:
        if ijk[0] > MAX_FACE_COORD or ijk[1] > MAX_FACE_COORD or ijk[2] > MAX_FACE_COORD:
            return 0
        base, _rot = FACE_IJK_BASE_CELLS[face][ijk[0]][ijk[1]][ijk[2]]
        h |= base << H3_BC_OFFSET
        return h
    for r in range(res - 1, -1, -1):
        last = list(ijk)
        if (r + 1) % 2:
            _up_ap7(ijk)
            center = list(ijk)
            _down_ap7(center)
        else:
            _up_ap7r(ijk)
            center = list(ijk)
            _down_ap7r(center)
        diff = [last[0] - center[0], last[1] - center[1], last[2] - center[2]]
        _ijk_normalize(diff)
        h = _h3_set_digit(h, r + 1, _unit_ijk_to_digit(diff))
    if ijk[0] > MAX_FACE_COORD or ijk[1] > MAX_FACE_COORD or ijk[2] > MAX_FACE_COORD:
        return 0
    base, num_rots = FACE_IJK_BASE_CELLS[face][ijk[0]][ijk[1]][ijk[2]]
    h |= base << H3_BC_OFFSET
    if BASE_CELL_IS_PENT[base]:
        if _h3_leading_nonzero(h) == K_AXES_DIGIT:
            cw0, cw1 = BASE_CELL_CW_OFFSET[base]
            if cw0 == face or cw1 == face:
                h = _h3_rotate60cw(h)
            else:
                h = _h3_rotate60ccw(h)
        for _ in range(num_rots):
            h = _h3_rotate_pent60ccw(h)
    else:
        for _ in range(num_rots):
            h = _h3_rotate60ccw(h)
    return h


def _latlng_to_cell(lat, lon, resolution):
    """Encode lat/lng with the bundled H3 algorithm (no compiled h3 package)."""
    res = int(resolution)
    if res < 0 or res > MAX_H3_RES:
        raise ValueError("H3 resolution must be between 0 and 15.")
    lat = float(lat)
    lon = float(lon)
    if not math.isfinite(lat) or not math.isfinite(lon):
        raise ValueError("Latitude and longitude must be finite numbers.")
    lat_r = lat * M_PI_180
    lon_r = lon * M_PI_180
    face, x, y = _geo_to_hex2d(lat_r, lon_r, res)
    coord = _hex2d_to_coord_ijk(x, y)
    index = _face_ijk_to_h3(face, coord, res)
    if not index:
        raise ValueError("Could not encode H3 cell for this location.")
    return format(index, "x")


def latlng_to_cell(lat, lon, resolution=9):
    """H3 cell identifier as a lowercase hex string (Uber H3 latLngToCell)."""
    try:
        import h3

        if hasattr(h3, "latlng_to_cell"):
            return str(h3.latlng_to_cell(float(lat), float(lon), int(resolution)))
        if hasattr(h3, "geo_to_h3"):
            return str(h3.geo_to_h3(float(lat), float(lon), int(resolution)))
    except ImportError:
        pass
    return _latlng_to_cell(lat, lon, resolution)
